SET ROLE hub2_mem_owner;
CREATE TABLE mem.upload_sessions(operation_id uuid PRIMARY KEY REFERENCES mem.operations(id),mode text NOT NULL CHECK(mode IN ('put','multipart')),state text NOT NULL DEFAULT 'starting',part_size bigint CHECK((mode='put' AND part_size IS NULL) OR (mode='multipart' AND part_size IS NOT NULL AND part_size BETWEEN 5242880 AND 5368709120)),upload_id text CHECK(mode<>'multipart' OR state='starting' OR (upload_id IS NOT NULL AND length(upload_id)>0)),lease_token uuid NOT NULL DEFAULT gen_random_uuid(),lease_until timestamptz NOT NULL DEFAULT now()+interval '1 minute',provider_receipt jsonb);
CREATE TABLE mem.upload_tickets(operation_id uuid NOT NULL REFERENCES mem.operations(id),part_number integer NOT NULL,size bigint NOT NULL,expires_at timestamptz NOT NULL,PRIMARY KEY(operation_id,part_number));
CREATE FUNCTION mem.upload_control(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$
DECLARE b jsonb:=payload::jsonb;c jsonb;o mem.operations;s mem.upload_sessions;command text:=b->>'command';n integer;partsize bigint;countparts bigint; BEGIN
IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;c:=mem.guard(h,'mem.upload',d);IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501';END IF;
SELECT * INTO o FROM mem.operations WHERE id=(b->>'operation_id')::uuid AND actor_id=(c->>'actor_id')::uuid AND project_id=(c->>'project_id')::uuid FOR UPDATE;IF NOT FOUND OR (o.state NOT IN ('prepared','uploading') AND command NOT IN ('list','resume','abort')) THEN RAISE EXCEPTION 'upload_state_conflict' USING ERRCODE='40001';END IF;
SELECT * INTO s FROM mem.upload_sessions WHERE operation_id=o.id FOR UPDATE;
IF command='begin' THEN
IF s.operation_id IS NOT NULL THEN IF s.mode<>b->>'mode' OR (s.mode='multipart' AND s.part_size IS DISTINCT FROM (b->>'part_size')::bigint) THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='23505';END IF;IF s.state='starting' THEN IF s.lease_until>clock_timestamp() THEN RAISE EXCEPTION 'upload_lease_busy' USING ERRCODE='55P03';END IF;PERFORM authz.assert_effect(h); UPDATE mem.upload_sessions SET lease_token=gen_random_uuid(),lease_until=clock_timestamp()+interval '1 minute' WHERE operation_id=o.id RETURNING * INTO s;END IF;
ELSE IF b->>'mode'='multipart' THEN partsize:=(b->>'part_size')::bigint;IF partsize IS NULL OR partsize<5242880 OR partsize>5368709120 OR o.expected_size<=0 OR ceil(o.expected_size::numeric/partsize)>10000 THEN RAISE EXCEPTION 'invalid_part_size';END IF;END IF;PERFORM authz.assert_effect(h); INSERT INTO mem.upload_sessions(operation_id,mode,part_size) VALUES(o.id,b->>'mode',partsize) RETURNING * INTO s;PERFORM authz.assert_effect(h); UPDATE mem.operations SET state='uploading' WHERE id=o.id;END IF;
ELSIF command='bind' THEN IF s.state<>'starting' OR s.lease_token IS DISTINCT FROM (b->>'lease_token')::uuid OR s.lease_until<=clock_timestamp() THEN RAISE EXCEPTION 'upload_lease_conflict' USING ERRCODE='40001';END IF;PERFORM authz.assert_effect(h); UPDATE mem.upload_sessions SET upload_id=b->>'upload_id',state='open',lease_until=clock_timestamp()+interval '1 hour' WHERE operation_id=o.id RETURNING * INTO s;
ELSIF command='ticket' THEN IF s.state<>'open' OR s.lease_until<=clock_timestamp() THEN RAISE EXCEPTION 'upload_lease_conflict' USING ERRCODE='40001';END IF;n:=COALESCE((b->>'part_number')::integer,0);partsize:=(b->>'size')::bigint;IF s.mode='put' THEN IF n<>0 OR partsize<>o.expected_size OR partsize>5368709120 THEN RAISE EXCEPTION 'invalid_upload_size';END IF;ELSE countparts:=ceil(o.expected_size::numeric/s.part_size);IF n<1 OR n>countparts OR partsize<>(CASE WHEN n=countparts THEN o.expected_size-(n-1)*s.part_size ELSE s.part_size END) THEN RAISE EXCEPTION 'invalid_part_size';END IF;END IF;
IF NOT EXISTS(SELECT 1 FROM mem.upload_tickets WHERE operation_id=o.id AND part_number=n AND expires_at>clock_timestamp()) AND (SELECT count(*) FROM mem.upload_tickets WHERE operation_id=o.id AND expires_at>clock_timestamp())>=8 THEN RAISE EXCEPTION 'upload_concurrency_limit' USING ERRCODE='55P03';END IF;PERFORM authz.assert_effect(h); INSERT INTO mem.upload_tickets VALUES(o.id,n,partsize,clock_timestamp()+interval '300 seconds') ON CONFLICT(operation_id,part_number) DO UPDATE SET size=EXCLUDED.size,expires_at=EXCLUDED.expires_at;PERFORM authz.assert_effect(h); UPDATE mem.upload_sessions SET lease_until=clock_timestamp()+interval '1 hour' WHERE operation_id=o.id RETURNING * INTO s;
ELSIF command='parts_seen' THEN IF s.mode<>'multipart' OR s.state<>'open' THEN RAISE EXCEPTION 'upload_state_conflict' USING ERRCODE='40001';END IF;PERFORM authz.assert_effect(h); DELETE FROM mem.upload_tickets WHERE operation_id=o.id AND part_number IN (SELECT (value->>'part_number')::integer FROM jsonb_array_elements(b->'parts'));
ELSIF command IN ('list','resume') THEN IF s.state NOT IN ('open','completing','completed','aborted') THEN RAISE EXCEPTION 'upload_state_conflict' USING ERRCODE='40001';END IF;IF command='resume' AND s.state='open' THEN PERFORM authz.assert_effect(h); UPDATE mem.upload_sessions SET lease_until=clock_timestamp()+interval '1 hour' WHERE operation_id=o.id RETURNING * INTO s;END IF;
ELSIF command IN ('complete','abort') THEN IF s.state IN ('completed','aborted') THEN RETURN jsonb_build_object('operation_id',o.id,'state',s.state,'receipt',s.provider_receipt);END IF;IF s.state IN ('completing','aborting') AND s.lease_until>clock_timestamp() THEN RAISE EXCEPTION 'upload_lease_busy' USING ERRCODE='55P03';END IF;PERFORM authz.assert_effect(h); UPDATE mem.upload_sessions SET state=CASE WHEN command='complete' THEN 'completing' ELSE 'aborting' END,lease_token=gen_random_uuid(),lease_until=clock_timestamp()+interval '1 minute' WHERE operation_id=o.id RETURNING * INTO s;
ELSIF command='finish' THEN IF s.lease_token IS DISTINCT FROM (b->>'lease_token')::uuid OR s.lease_until<=clock_timestamp() OR s.state NOT IN ('completing','aborting') THEN RAISE EXCEPTION 'upload_lease_conflict' USING ERRCODE='40001';END IF;PERFORM authz.assert_effect(h); UPDATE mem.upload_sessions SET state=CASE WHEN state='completing' OR b->'receipt'->>'state'='already_completed' THEN 'completed' ELSE 'aborted' END,provider_receipt=b->'receipt' WHERE operation_id=o.id RETURNING * INTO s;IF s.state='aborted' THEN PERFORM authz.assert_effect(h); UPDATE mem.operations SET state='cancelled' WHERE id=o.id;END IF;
ELSE RAISE EXCEPTION 'invalid_upload_command';END IF;
RETURN jsonb_build_object('operation_id',o.id,'state',s.state,'mode',s.mode,'staging_key',o.staging_key,'size',o.expected_size,'sha256',o.expected_hash,'part_size',s.part_size,'upload_id',s.upload_id,'lease_token',s.lease_token,'lease_until',s.lease_until,'receipt',s.provider_receipt);END $$;
CREATE FUNCTION mem.gc_candidates(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;items jsonb;BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;c:=mem.guard(h,'mem.delete',d);IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501';END IF;SELECT COALESCE(jsonb_agg(jsonb_build_object('operation_id',o.id,'state',o.state,'candidate_kind','terminal_staging','has_verified_object',o.object_id IS NOT NULL,'protected_formal_versions',(SELECT count(*) FROM mem.content_versions v WHERE v.object_id=o.object_id),'decision','hold','reason','restore_manifest_and_retention_not_confirmed')),'[]') INTO items FROM mem.operations o WHERE project_id=(c->>'project_id')::uuid AND state IN ('cancelled','expired','rejected','conflict') AND created_at<clock_timestamp()-interval '1 day';RETURN jsonb_build_object('state','dry_run','coverage','authorized_project_terminal_candidates','candidates',items,'deletion_performed',false,'decision','hold','restore_window','unconfirmed','next_step','confirm_external_restore_manifest_and_retention');END $$;
REVOKE ALL ON ALL TABLES IN SCHEMA mem FROM PUBLIC,hub2_mem;
REVOKE ALL ON FUNCTION mem.upload_control(uuid,text,text),mem.gc_candidates(uuid,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mem.upload_control(uuid,text,text),mem.gc_candidates(uuid,text,text) TO hub2_mem;
RESET ROLE;
GRANT SELECT(actor_id) ON mem.content_versions TO hub2_v8_owner;
